{"implementation": "def solve(case):
    nodes = list(case.get('nodes', []))
    required_symbols = set(case.get('required_symbols', []))

    by_id = {}
    parent_by_id = {}
    for node in nodes:
        node_id = node.get('id')
        by_id[node_id] = node
        parent_by_id[node_id] = node.get('parent')

    retained = set()

    for node in nodes:
        if not node.get('removable', False) or node.get('symbol') in required_symbols:
            current = node.get('id')
            while current is not None and current in by_id and current not in retained:
                retained.add(current)
                current = parent_by_id.get(current)

    retained_node_ids = []
    removed_node_ids = []
    for node in nodes:
        node_id = node.get('id')
        if node_id in retained:
            retained_node_ids.append(node_id)
        else:
            removed_node_ids.append(node_id)

    return {
        'removed_node_ids': removed_node_ids,
        'retained_node_ids': retained_node_ids,
    }
"}
